sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    var tradeCase = new GlideRecord("x_hsb11_hsbc_mss_t_trade_case");
    tradeCase.initialize();
    tradeCase.global_mis_update = 'true';
    var mssSNAutomationGrpID = gs.getProperty("HSBC_MOCS_Group");
    tradeCase.setValue("assignment_group", mssSNAutomationGrpID);
    tradeCase.short_description = "Case created for Global MIS";
    var objectID = current.financial_object_record.getDisplayValue();
    tradeCase.financial_object.setDisplayValue(objectID);
    tradeCase.trade_status.setDisplayValue('Global MIS');
    tradeCase.u_fo_process_status.setDisplayValue('Global MIS');
    tradeCase.sub_status.setDisplayValue('Global MIS Error resolved');
    tradeCase.u_additional_attributes = current.additional_attributes;
    tradeCase.u_objectversion = current.object_version;
    tradeCase.u_event_type = current.event_type;
    tradeCase.u_objectidtype = current.objectid_type;
    tradeCase.u_object_type = current.object_type;
    var bpiValue = current.number.getDisplayValue();
    tradeCase.u_business_process_instance.setDisplayValue(bpiValue);
    tradeCase.u_message_id = current.messageid;
    tradeCase.u_source = current.source;
    var newobjectid = tradeCase.insert();
    current.is_case_created = true;
    current.payload = tradeCase.u_payload;
    current.setWorkflow(false);
    current.update();

        var updateTradeCase = new GlideRecord('x_hsb11_hsbc_mss_t_trade_case');
        updateTradeCase.addQuery('financial_object.u_id', objectID);
        updateTradeCase.addQuery('sys_id', '!=', newobjectid);
        updateTradeCase.query();
        while (updateTradeCase.next()) {
            updateTradeCase.auto_close = true;
            updateTradeCase.state = 7;
            updateTradeCase.update();
        }


})(current, previous);
